        if w in s: sc += 10
    return sc

def trithemius(s, start, step):
    o=[]; i=0
    for c in s:
        if 'a'<=c<='z': o.append(chr((ord(c)-97 - (start+step*i))%26+97)); i+=1
        elif c.isdigit(): o.append(str((int(c) - (start+step*i))%10)); i+=1
        else: o.append(c)
    return ''.join(o)

def railfence(s, rails, decode=False):
    if rails<2: return s
    pattern = list(range(rails)) + list(range(rails-2,0,-1))
    idx = [pattern[i % len(pattern)] for i in range(len(s))]
    if not decode:
        rows = ['' for _ in range(rails)]
        for c,r in zip(s,idx): rows[r]+=c
        return ''.join(rows)
    else:
        # decode: reconstruct
        counts = [idx.count(r) for r in range(rails)]
        res=['']*len(s); pos=0; pool=[]
        for r in range(rails):
            pool.append(s[pos:pos+counts[r]]); pos+=counts[r]
        ptr=[0]*rails
        for i,r in enumerate(idx):
            res[i]=pool[r][ptr[r]]; ptr[r]+=1
        return ''.join(res)

def scytale(s, period, phase=0):
    # read every period-th char starting at phase
    return s[phase::period]

def col_trans(s, key):
    # columnar transposition decode with numeric key permutation
    n=len(key)
    cols = [s[i::n] for i in range(n)]  # simplistic
    order = sorted(range(n), key=lambda i: key[i])
    out=''
    for r in range(0, max(len(c) for c in cols)):
        for i in order:
