def railfence(s, rails, decode=False):
    if rails<2: return s
    pattern = list(range(rails)) + list(range(rails-2,0,-1))
    idx = [pattern[i % len(pattern)] for i in range(len(s))]
    if not decode:
        rows = ['' for _ in range(rails)]
        for c,r in zip(s,idx): rows[r]+=c
        return ''.join(rows)
    else:
