import os
words = [w.strip().lower() for w in open('words.txt') if w.strip().isalpha() and 3<=len(w.strip())<=12]
def alpha_variants(keyword):
    base="abcdefghijklmnopqrstuvwxyz"
    seen=[]
    for c in keyword:
        if c not in seen: seen.append(c)
    rest=[c for c in base if c not in seen]
    out = {}
    out['append'] = ''.join(seen+rest)
    out['append_rev'] = ''.join(seen+rest[::-1])
    out['prepend'] = ''.join(rest[::-1]+seen)   # uncommon
    # columnar: write keyword rows into 5-col grid
    kw = ''.join(seen)
    for ncols in (5,6,7):
        grid = kw + ''.join(rest)
        cols = [''.join(grid[i::ncols]) for i in range(ncols)]
        out[f'col{ncols}'] = ''.join(cols)
    return out
